<?php
/**
 * KosmoEngine Installer v3.2 — Автономный установщик
 * Содержит ВСЕ файлы проекта. Загрузите ТОЛЬКО этот файл на хостинг.
 * УДАЛИТЕ ПОСЛЕ УСТАНОВКИ!
 */
error_reporting(E_ALL); ini_set('display_errors',1); set_time_limit(600);
header('Content-Type: text/html; charset=UTF-8');
$step=$_GET['step']??'check'; $error=''; $success='';

function slugify($t){$m=['а'=>'a','б'=>'b','в'=>'v','г'=>'g','д'=>'d','е'=>'e','ё'=>'yo','ж'=>'zh','з'=>'z','и'=>'i','й'=>'y','к'=>'k','л'=>'l','м'=>'m','н'=>'n','о'=>'o','п'=>'p','р'=>'r','с'=>'s','т'=>'t','у'=>'u','ф'=>'f','х'=>'kh','ц'=>'ts','ч'=>'ch','ш'=>'sh','щ'=>'shch','ъ'=>'','ы'=>'y','ь'=>'','э'=>'e','ю'=>'yu','я'=>'ya'];return trim(preg_replace('/[^a-z0-9]+/','-',strtr(mb_strtolower($t),$m)),'-').'-'.substr(uniqid(),-6);}

// ШАГ: Распаковка файлов
if($step==='extract'&&$_SERVER['REQUEST_METHOD']==='POST'){
    try{
        $tmp=__DIR__.'/_kosmo_tmp.tar.gz';
        $raw=base64_decode(getEmbeddedArchive());
        if(!$raw||strlen($raw)<100) throw new Exception('Ошибка декодирования');
        file_put_contents($tmp,$raw);
        
        // Распаковка через tar
        $cmd='cd '.escapeshellarg(__DIR__).' && tar xzf _kosmo_tmp.tar.gz 2>&1';
        shell_exec($cmd);
        
        // Если tar не сработал — PharData
        if(!file_exists(__DIR__.'/config.php')&&class_exists('PharData')){
            $phar=new PharData($tmp);
            $phar->extractTo(__DIR__,null,true);
        }
        
        @unlink($tmp);
        
        if(!file_exists(__DIR__.'/config.php')||!file_exists(__DIR__.'/index.php'))
            throw new Exception('Файлы не распакованы');
        
        // Создаём .htaccess
        if(!file_exists(__DIR__.'/.htaccess')){
            $htaccess = "AddDefaultCharset UTF-8\n\nRewriteEngine On\n\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule ^(.*)$ index.php [QSA,L]\n\n<IfModule mod_expires.c>\nExpiresActive On\nExpiresByType image/jpeg \"access plus 1 month\"\nExpiresByType image/png \"access plus 1 month\"\nExpiresByType image/svg+xml \"access plus 1 month\"\nExpiresByType text/css \"access plus 1 week\"\nExpiresByType application/javascript \"access plus 1 week\"\n</IfModule>\n\n<IfModule mod_deflate.c>\nAddOutputFilterByType DEFLATE text/html text/css application/javascript application/json image/svg+xml\n</IfModule>\n\n<FilesMatch \"\\.(env|log|json|txt)$\">\n<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n</FilesMatch>\n\n<FilesMatch \"^\\.\">\n<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n</FilesMatch>\n";
            file_put_contents(__DIR__.'/.htaccess', $htaccess);
        }
        
        // Создаём директории
        foreach(['data','data/cache','data/geo_cache','images/articles','images/offer'] as $d)
            @mkdir(__DIR__.'/'.$d,0755,true);
        
        $cnt=count(glob(__DIR__.'/{_admin,_api,_api/admin,includes,pages}/*.php',GLOB_BRACE));
        $step='config';
        $success="Файлы распакованы! ($cnt PHP файлов, .htaccess создан)";
    }catch(Exception $e){
        $error=$e->getMessage();
        @unlink(__DIR__.'/_kosmo_tmp.tar.gz');
    }
}

// ШАГ: Установка БД
if($step==='install'&&$_SERVER['REQUEST_METHOD']==='POST'){
    $h=trim($_POST['db_host']??'localhost');$n=trim($_POST['db_name']??'');$u=trim($_POST['db_user']??'');$p=$_POST['db_pass']??'';
    $au=trim($_POST['admin_user']??'admin');$ap=$_POST['admin_pass']??'';
    $sn=trim($_POST['site_name']??'Космозайм');$su=trim($_POST['site_url']??'');
    if(!$n||!$u){$error='Заполните данные БД';}
    elseif(strlen($ap)<6){$error='Пароль мин. 6 символов';}
    else{try{
        $pdo=new PDO("mysql:host=$h;charset=utf8mb4",$u,$p,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
        $pdo->exec("CREATE DATABASE IF NOT EXISTS `$n` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci");
        $pdo->exec("USE `$n`");
        $queries=array_filter(array_map('trim',preg_split('/;\s*[\r\n]+/',getDbSchema())));
        foreach($queries as $q){if($q&&!preg_match('/^--/',$q))$pdo->exec($q);}
        
        $hash=password_hash($ap,PASSWORD_DEFAULT);
        $pdo->prepare("INSERT INTO admin_users (username,password_hash) VALUES (?,?) ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash)")->execute([$au,$hash]);
        
        $tags=[['bez-otkaza','Займы без отказа','✅','microloans','Высокий процент одобрения'],['bez-protsentov','Займы без процентов','🆓','microloans','Первый займ под 0%'],['na-kartu','Займы на карту','💳','microloans','Мгновенно на карту'],['s-plohoj-ki','С плохой КИ','📊','microloans','Без проверки КИ'],['dlya-pensionerov','Для пенсионеров','👴','microloans','До 75 лет'],['studentam','Для студентов','🎓','microloans','От 18 лет']];
        $st=$pdo->prepare("INSERT IGNORE INTO offer_tags (slug,title,icon,category,description,is_active,sort_order) VALUES (?,?,?,?,?,1,?)");
        foreach($tags as $i=>$t)$st->execute([$t[0],$t[1],$t[2],$t[3],$t[4],$i+1]);
        
        $offers=[['Пример МФО 1','microloans',1000,30000,0.8,'day',14,'Быстрые займы онлайн'],['Пример МФО 2','microloans',5000,100000,0.99,'day',7,'Деньги за 5 минут'],['Пример Банк','credits',50000,5000000,15.9,'year',0,'Кредит наличными'],['Пример Карта','credit_cards',0,500000,24.9,'year',55,'Кредитная карта']];
        $st=$pdo->prepare("INSERT INTO offers (title,slug,category,amount_min,amount_max,rate,rate_unit,free_term_days,affiliate_url,description,is_active,sort_order) VALUES (?,?,?,?,?,?,?,?,'',?,1,?)");
        foreach($offers as $i=>$o)$st->execute([$o[0],slugify($o[0]),$o[1],$o[2],$o[3],$o[4],$o[5],$o[6],$o[7],$i+1]);
        
        $pdo->exec("INSERT IGNORE INTO offer_tag_links (offer_id,tag_id) SELECT o.id,t.id FROM offers o,offer_tags t WHERE o.category='microloans' AND t.category='microloans'");
        
        file_put_contents(__DIR__.'/.env',"DB_HOST=$h\nDB_NAME=$n\nDB_USER=$u\nDB_PASS=$p\nSESSION_SECRET=".bin2hex(random_bytes(32))."\n");
        @chmod(__DIR__.'/.env',0600);
        @mkdir(__DIR__.'/data',0755,true);
        file_put_contents(__DIR__.'/data/site-settings.json',json_encode(['site_name'=>$sn,'site_url'=>$su?:'https://'.$_SERVER['HTTP_HOST']],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
        $step='done';
    }catch(PDOException $e){$error='Ошибка БД: '.$e->getMessage();}}
}

function getDbSchema(){return <<<'SQL'
CREATE TABLE IF NOT EXISTS `admin_users` (`id` int AUTO_INCREMENT PRIMARY KEY, `username` varchar(100) NOT NULL UNIQUE, `password_hash` varchar(255) NOT NULL, `totp_secret` varchar(64) DEFAULT NULL, `totp_enabled` tinyint(1) DEFAULT 0, `backup_codes` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `offers` (`id` int AUTO_INCREMENT PRIMARY KEY, `title` varchar(500) NOT NULL, `slug` varchar(500) NOT NULL UNIQUE, `category` enum('microloans','credits','credit_cards','debit_cards') DEFAULT 'microloans', `amount_min` int DEFAULT 1000, `amount_max` int DEFAULT 100000, `term_min_days` int DEFAULT 1, `term_max_days` int DEFAULT 365, `psk` decimal(10,2) DEFAULT 0, `rate` decimal(10,2) DEFAULT 0, `rate_unit` enum('day','year') DEFAULT 'day', `free_term_days` int DEFAULT 0, `logo_url` text, `affiliate_url` text, `borrower_category` varchar(50) DEFAULT 'any', `description` text, `seo_keywords` text, `regions` text, `rating` decimal(2,1) DEFAULT 5.0, `review_count` int DEFAULT 0, `is_active` tinyint(1) DEFAULT 1, `sort_order` int DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `age_min` int DEFAULT 18, `age_max` int DEFAULT 75, `documents` text, `requirements` text, `advantages` text, `application_time` varchar(100), `review_time` varchar(100), `payout_methods` text, `about_company` text, `meta_title` varchar(500), `meta_description` text, `features` text, `faq` text) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `articles` (`id` int AUTO_INCREMENT PRIMARY KEY, `title` varchar(500) NOT NULL, `slug` varchar(500) NOT NULL UNIQUE, `excerpt` text, `content` text NOT NULL, `meta_title` varchar(255), `meta_description` text, `cover_image` text, `is_published` tinyint(1) DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `reviews` (`id` int AUTO_INCREMENT PRIMARY KEY, `offer_id` int NOT NULL, `author_name` varchar(255) NOT NULL, `rating` int DEFAULT 5, `text` text NOT NULL, `pros` text, `cons` text, `is_approved` tinyint(1) DEFAULT 1, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `offer_id` (`offer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `click_stats` (`id` int AUTO_INCREMENT PRIMARY KEY, `offer_id` int NOT NULL, `user_agent` text, `referer` text, `ip` varchar(50), `utm_source` varchar(255), `utm_medium` varchar(255), `utm_campaign` varchar(255), `utm_content` varchar(255), `utm_term` varchar(255), `page_from` text, `ab_variant_id` int, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `offer_id` (`offer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `subscribers` (`id` int AUTO_INCREMENT PRIMARY KEY, `email` varchar(255) NOT NULL UNIQUE, `is_active` tinyint(1) DEFAULT 1, `source` varchar(100), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `geo_redirects` (`id` int AUTO_INCREMENT PRIMARY KEY, `city_name` varchar(255) NOT NULL, `slug` varchar(255) NOT NULL UNIQUE, `region` varchar(255), `is_active` tinyint(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `offer_tags` (`id` int AUTO_INCREMENT PRIMARY KEY, `slug` varchar(255) NOT NULL UNIQUE, `title` varchar(255) NOT NULL, `h1` varchar(500), `description` text, `meta_description` text, `content` text, `icon` varchar(10), `category` enum('microloans','credits','credit_cards','debit_cards') DEFAULT 'microloans', `features` text, `is_active` tinyint(1) DEFAULT 1, `sort_order` int DEFAULT 0, `search_queries` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `offer_tag_links` (`id` int AUTO_INCREMENT PRIMARY KEY, `offer_id` int NOT NULL, `tag_id` int NOT NULL, UNIQUE KEY `offer_tag` (`offer_id`,`tag_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `categories` (`id` int AUTO_INCREMENT PRIMARY KEY, `slug` varchar(255) NOT NULL UNIQUE, `name` varchar(255) NOT NULL, `title` varchar(500), `description` text, `meta_title` varchar(500), `meta_description` text, `icon` varchar(50), `parent_id` int, `category_type` enum('microloans','credits','credit_cards','debit_cards') DEFAULT 'microloans', `filter_json` text, `content_top` text, `content_bottom` text, `is_active` tinyint(1) DEFAULT 1, `sort_order` int DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `page_views` (`id` int AUTO_INCREMENT PRIMARY KEY, `page` varchar(500) NOT NULL, `ip` varchar(50), `utm_source` varchar(255), `utm_medium` varchar(255), `utm_campaign` varchar(255), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `admin_login_log` (`id` int AUTO_INCREMENT PRIMARY KEY, `username` varchar(100), `ip` varchar(50), `user_agent` text, `success` tinyint(1) DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `admin_ip_whitelist` (`id` int AUTO_INCREMENT PRIMARY KEY, `ip` varchar(50) NOT NULL UNIQUE, `description` varchar(255), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `audit_log` (`id` int AUTO_INCREMENT PRIMARY KEY, `admin_id` int, `action` varchar(100) NOT NULL, `entity_type` varchar(50), `entity_id` int, `old_data` text, `new_data` text, `ip` varchar(50), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `city_seo` (`id` int AUTO_INCREMENT PRIMARY KEY, `city_slug` varchar(255) NOT NULL, `page_type` varchar(50) NOT NULL, `h1` varchar(500), `title` varchar(500), `description` text, `content` text, `faq` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY `city_page` (`city_slug`,`page_type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `users` (`id` int AUTO_INCREMENT PRIMARY KEY, `email` varchar(255) NOT NULL UNIQUE, `phone` varchar(20), `password_hash` varchar(255) NOT NULL, `name` varchar(255), `is_active` tinyint(1) DEFAULT 1, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `user_favorites` (`id` int AUTO_INCREMENT PRIMARY KEY, `user_id` int NOT NULL, `offer_id` int NOT NULL, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY `user_offer` (`user_id`,`offer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `user_applications` (`id` int AUTO_INCREMENT PRIMARY KEY, `user_id` int NOT NULL, `offer_id` int NOT NULL, `click_stat_id` int, `ip` varchar(50), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `conversions` (`id` int AUTO_INCREMENT PRIMARY KEY, `click_id` int, `offer_id` int, `status` varchar(50), `payout` decimal(10,2) DEFAULT 0, `currency` varchar(10) DEFAULT 'RUB', `external_id` varchar(255), `raw_data` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ab_tests` (`id` int AUTO_INCREMENT PRIMARY KEY, `name` varchar(255) NOT NULL, `offer_id` int, `scope` enum('offer','global') DEFAULT 'offer', `is_active` tinyint(1) DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ab_variants` (`id` int AUTO_INCREMENT PRIMARY KEY, `test_id` int NOT NULL, `name` varchar(255) NOT NULL, `button_text` varchar(255), `button_color` varchar(50), `cta_text` text, `weight` int DEFAULT 50, `views` int DEFAULT 0, `clicks` int DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `newsletters` (`id` int AUTO_INCREMENT PRIMARY KEY, `subject` varchar(500) NOT NULL, `content` text NOT NULL, `status` enum('draft','scheduled','sending','sent') DEFAULT 'draft', `scheduled_at` datetime, `sent_at` datetime, `sent_count` int DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `postback_profiles` (`id` int AUTO_INCREMENT PRIMARY KEY, `name` varchar(255) NOT NULL, `type` varchar(50) DEFAULT 'leads_su', `config` text, `is_active` tinyint(1) DEFAULT 1, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SQL;
}

